-- Drop the orphaned BoostTurn table.
--
-- 020 created it, then step 3 removed it from schema.prisma when the model
-- changed from a single global slot to per-viewer assignment. Removing a model
-- from the schema does NOT drop the table - it just stops Prisma using it. The
-- table stayed behind, empty and readable with the anon key.
--
-- Verified against pg_class before writing this: BoostTurn exists, rls_enabled
-- = FALSE, and no model references it any more.
--
-- Type names checked against pg_type: there is a "BoostTurn" type generated by
-- the table, but NO "BoostSurface" type - that enum was declared in the schema
-- and never created in the database. Only the real names are dropped here.

DROP TABLE IF EXISTS "BoostTurn" CASCADE;
DROP TYPE IF EXISTS "BoostTurn" CASCADE;
